import os
O = os.environ.get("NFB_OUT", (_os.environ.get("SIGNALS_ROOT", ".") + "/out/")).rstrip("/") + "/"
a = pd.read_csv(O + "r9_all_runs.csv"); b = pd.read_csv(O + "r9_bootstrap.csv")
def g(S, fix, w, col): return a[(a.S == S * 1e6) & (a.fix == fix) & (a.win == w)][col].iloc[0]
def row(S, fix, label):
    c = []
    for w in ("IS", "HO", "FY"): c += [f"{g(S,fix,w,'ann'):.1f}", f"{g(S,fix,w,'net_u')/1e4:.0f}"]
    c.append(f"{g(S,fix,'FY','avg_cost_used_u')/1e4:.0f}")
    return f"| {label} | " + " | ".join(c) + " |"
